import { readFile, writeFile } from 'node:fs/promises';

const samplerPath = new URL('../node_modules/openapi-sampler/dist/openapi-sampler.js', import.meta.url);
const hydratorPath = new URL('../internal/web/static/schema-example-hydrator.js', import.meta.url);
const outputPath = new URL('../internal/web/static/schema-example.js', import.meta.url);

const [sampler, hydrator] = await Promise.all([
  readFile(samplerPath, 'utf8'),
  readFile(hydratorPath, 'utf8'),
]);

await writeFile(
  outputPath,
  [
    '// Code generated by scripts/build-schema-example-asset.mjs; DO NOT EDIT.',
    sampler.trimEnd(),
    ';',
    hydrator.trimEnd(),
    '',
  ].join('\n'),
);
